泛型工具：
&#47;&#47; NonNullable&lt;T&gt;:去除类型中的null和undefined
type P1 = NonNullable&lt;string | number | null | undefined&gt;;
&#47;&#47; Exclude&lt;T,ExcludedUnion&gt;:将某个类型中属于另一个的类型移除掉，剩余的部分构成新的类型
type U = &#39;d&#39; | &#39;g&#39; | &#39;h&#39; | &#39;q&#39; | &#39;w&#39; | &#39;e&#39; | &#39;t&#39; | &#39;y&#39;;
type P2 = Exclude&lt;U, &#39;d&#39; | &#39;h&#39;&gt;;
&#47;&#47; Extract&lt;T,Union&gt;:从T中提取Union，相当于并集
type P3 = Extract&lt;U, &#39;h&#39; | &#39;q&#39;&gt;;
&#47;&#47; Required&lt;T&gt;:将类型的属性变为必选
interface Person {
  name: string;
  age: number;
}
const user: Required&lt;Person&gt; = {
  name: &#39;123&#39;,
  age: 10,
}
&#47;&#47; Partial&lt;T&gt;:将所有属性变为可选
const usre1: Partial&lt;Person&gt; = {
  name:&#39;78964&#39;
}
&#47;&#47; Readonly&lt;T&gt;:数组或者对象的说有属性值转换为只读，这些属性不能被重新赋值
const user2: Readonly&lt;Person&gt; = {
  name: &#39;123&#39;,
  age: 10
}
&#47;&#47; user2.age = 13;只读的
&#47;&#47; pick&lt;T,Keys&gt;:从某个类型中挑出一些属性出来
const user3: Pick&lt;Person, &#39;name&#39;&gt; = {
  name:&#39;741&#39;
}
&#47;&#47; Omit&lt;T,keys&gt;:从某个类型中取出去keys的其他属性
type P4 = Omit&lt;Person, &#39;name&#39;&gt;;
&#47;&#47; InstanceType&lt;T&gt;:用于获取一个类的实力类型
class MyClass{
  y = 10;
  x = 3;
}
type P7 = InstanceType&lt;typeof MyClass&gt;;
&#47;&#47; Parameters&lt;T&gt;:用于获取函数的参数类型所组成的元组类型
type P5 = Parameters&lt;(a: string, b: number, c: boolean) =&gt; void&gt;;
&#47;&#47; ReturnType&lt;T&gt;:用来的到一个函数的返回值类型
type P6 = ReturnType&lt;() =&gt; string&gt;;
&#47;&#47; ConstructorParameters&lt;T&gt;:用于构造函数参数类型
class M {
  constructor(public x: number, public y: string) {

  }
}
type P8 = ConstructorParameters&lt;typeof M&gt;;
&#47;&#47; ThisParameterType&lt;T&gt;:提取函数类型T的this参数类型
function fn(this: number) {
  return this.toString(412745)
}
type P9 = ThisParameterType&lt;typeof fn&gt;;
&#47;&#47;OmitThisParameter&lt;T&gt;:从函数类型T中移除this参数
type P10 = OmitThisParameter&lt;typeof fn&gt;;
&#47;&#47; Awaited&lt;T&gt;:获取Promise的解析值类型
type P11 = Promise&lt;Promise&lt;string&gt;&gt;;
type P12 = Awaited&lt;P11&gt;;
